#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate and check the index of goat's public repositories.

    index.py --write    read the organization, rewrite docs/reference/repositories.md
    index.py --check    exit 1 when the page is missing a public repository,
                        lists one that is not public, or differs from what
                        --write would write (CI: .github/workflows/repositories.yml)
    index.py --from repos.json --check
                        the same, from a saved `gh repo list` output

The organization is read through the GitHub CLI (`gh`), so it uses whatever
token `gh` has: GH_TOKEN in a workflow, your own login on a laptop. Only
public repositories are read. Which section a repository is listed in comes
from sections.toml beside this file; what the line says is the repository's
own GitHub description. The same input always gives the same page.
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import tomllib

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
SECTIONS = os.path.join(HERE, "sections.toml")
PAGE = os.path.join(ROOT, "docs", "reference", "repositories.md")
FIELDS = "name,description,isArchived,url"
PREFIX = "Hello Galaxy — "


def load_sections(path: str = SECTIONS) -> dict:
    with open(path, "rb") as handle:
        config = tomllib.load(handle)
    config.setdefault("planned", {})
    config.setdefault("outside", {})
    return config


def read_org(org: str) -> list[dict]:
    run = subprocess.run(
        ["gh", "repo", "list", org, "--visibility", "public", "--limit", "500", "--json", FIELDS],
        capture_output=True, text=True)
    if run.returncode != 0:
        raise SystemExit(f"index: gh repo list {org} failed: {run.stderr.strip()}")
    return json.loads(run.stdout or "[]")


def problems(config: dict, repos: list[dict]) -> list[str]:
    """What is wrong between sections.toml and the public repositories."""
    public = {repo["name"]: repo for repo in repos}
    named: dict[str, str] = {}
    found = []
    for section in config["section"]:
        for name in section["repositories"]:
            if name in named:
                found.append(f"{name} is named in both '{named[name]}' and '{section['title']}'")
            named[name] = section["title"]
    for name in sorted(public, key=str.lower):
        repo = public[name]
        if repo.get("isArchived"):
            continue
        if name not in named and name not in config["outside"]:
            found.append(f"{name} is public and not in the index: add it to a section of "
                         f".github/repositories/sections.toml, or to [outside] if it is not goat's")
    for name, title in sorted(named.items()):
        if name not in public and name not in config["planned"]:
            found.append(f"{name} (in '{title}') is not a public repository: remove it, "
                         f"or add it to [planned] until it is published")
        if name in public and name in config["planned"]:
            found.append(f"{name} is public now: remove its [planned] entry")
    for name in config["planned"]:
        if name not in named:
            found.append(f"{name} is in [planned] but in no section")
    for name in config["outside"]:
        if name in named:
            found.append(f"{name} is in [outside] and in '{named[name]}'")
    return found


def line(org: str, name: str, repo: dict | None, planned: str | None) -> str:
    url = f"https://github.com/{org}/{name}"
    if repo is None:
        return f"- **{name}** (not public yet): {planned}"
    text = (repo.get("description") or "").strip() or "No description."
    if text.startswith(PREFIX):
        text = text[len(PREFIX):]
    return f"- [{name}]({repo.get('url') or url}): {text}"


def render(config: dict, repos: list[dict], org: str) -> str:
    public = {repo["name"]: repo for repo in repos}
    out = [
        "# goat's repositories",
        "",
        f"Every public repository of goat, the self-hosted open-source data fabric, grouped by what a reader comes for. "
        f"Each line is the repository's own description on GitHub.",
        "",
        f"This page is generated by [`.github/repositories/index.py`](../../.github/repositories/index.py) "
        f"from the public repositories of [{org}](https://github.com/{org}) and the sections in "
        f"[`.github/repositories/sections.toml`](../../.github/repositories/sections.toml). "
        f"[`repositories.yml`](../../.github/workflows/repositories.yml) fails when a public repository "
        f"is missing from it. Work that others build on goat is listed in "
        f"[awesome-goat](https://github.com/{org}/awesome-goat).",
        "",
    ]
    for section in config["section"]:
        out += [f"## {section['title']}", "", section["about"], ""]
        for name in section["repositories"]:
            repo = public.get(name)
            if repo is not None and repo.get("isArchived"):
                continue
            out.append(line(org, name, repo, config["planned"].get(name)))
        out.append("")
    archived = sorted((r for r in repos if r.get("isArchived")), key=lambda r: r["name"].lower())
    if archived:
        out += ["## Archived", "", "Read-only: kept for reference, no longer developed.", ""]
        out += [line(org, r["name"], r, None) for r in archived]
        out.append("")
    outside = [name for name in config["outside"] if name in public and not public[name].get("isArchived")]
    if outside:
        out += ["## Also in the organization", "", "Public repositories that are not part of goat.", ""]
        out += [f"- [{name}](https://github.com/{org}/{name}): {config['outside'][name]}" for name in outside]
        out.append("")
    return "\n".join(out)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--org", default="USAREUR-AF")
    parser.add_argument("--from", dest="source", metavar="FILE",
                        help="a saved `gh repo list --json name,description,isArchived,url` output")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    config = load_sections()
    if args.source:
        with open(args.source, encoding="utf-8") as handle:
            repos = json.load(handle)
    else:
        repos = read_org(args.org)
    found = problems(config, repos)
    for problem in found:
        print(f"FAIL {problem}")
    page = render(config, repos, args.org)
    if args.write:
        if found:
            return 1
        with open(PAGE, "w", encoding="utf-8") as handle:
            handle.write(page)
        print(f"wrote {os.path.relpath(PAGE, ROOT)}")
        return 0
    try:
        with open(PAGE, encoding="utf-8") as handle:
            current = handle.read()
    except FileNotFoundError:
        current = ""
    if current != page:
        print(f"FAIL {os.path.relpath(PAGE, ROOT)} is out of date: run "
              f"python3 .github/repositories/index.py --write and commit the result")
        found.append("stale page")
    if not found:
        print(f"index: {os.path.relpath(PAGE, ROOT)} lists every public repository of {args.org}")
    return 1 if found else 0


if __name__ == "__main__":
    raise SystemExit(main())
